554	}
555	
556	.tooltip:hover::after,
557	.tooltip:focus-visible::after {
558	  opacity: 1;
559	  bottom: 90%;
560	}
561	
562	.tooltip::before {
563	  content: '';
564	  position: absolute;
565	  bottom: 71%;
566	  left: 50%;
567	  transform: translateX(-50%);
568	  border: 6px solid transparent;
