18	// ─── Types ────────────────────────────────────────────────────────────────────
19	
20	interface CalcState {
21	  billing: BillingPeriod;
22	  plan: PlanKey;
23	  teamSize: number;
24	  manualHours: number;
25	  hourlyRate: number;
26	  toolCost: number;
27	}
28	
29	interface CalcResult {
30	  bmo: number;
31	  byr: number;
32	  laborSaved: number;
33	  savings: number;
34	  net: number;
35	  roi: number;
36	  monthlyBenefit: number;
37	  hrsSaved: number;
38	  prodGain: number;
39	}
