41	// ─── Helpers ─────────────────────────────────────────────────────────────────
42	
43	function fmt(n: number): string {
44	  return "$" + Math.round(n).toLocaleString("en-US");
45	}
46	
47	function fmtRoi(n: number): string {
48	  return Math.round(n).toLocaleString("en-US") + "%";
49	}
50	
51	function fmtHrs(n: number): string {
52	  return Math.round(n).toLocaleString("en-US") + " hrs";
53	}
54	
55	function fmtPct(n: number): string {
56	  return n.toFixed(1) + "%";
57	}
58	
59	function sliderBg(value: number, min: number, max: number): string {
60	  const pct = ((value - min) / (max - min)) * 100;
61	  return `linear-gradient(to right, #019ae6 0%, #019ae6 ${pct}%, #e2e8f0 ${pct}%, #e2e8f0 100%)`;
62	}
63	
64	// ─── Tooltip ─────────────────────────────────────────────────────────────────
65	
66	function Tooltip({ text }: { text: string }) {
67	  const [visible, setVisible] = useState(false);
68	  const id = useId();
69	
70	  return (
71	    <span className={styles.tooltipWrap}>
72	      <button
73	        type="button"
74	        className={styles.tooltipBtn}
75	        aria-describedby={visible ? id : undefined}
76	        aria-label="More information"
77	        onMouseEnter={() => setVisible(true)}
78	        onMouseLeave={() => setVisible(false)}
79	        onFocus={() => setVisible(true)}
80	        onBlur={() => setVisible(false)}
81	      >
82	        ?
83	      </button>
84	      {visible && (
85	        <span role="tooltip" id={id} className={styles.tooltipBubble}>
86	          {text}
87	        </span>
88	      )}
89	    </span>
90	  );
91	}
