93	// ─── Dollar input field ───────────────────────────────────────────────────────
94	
95	interface DollarFieldProps {
96	  label: string;
97	  tooltip: string;
98	  value: number;
99	  min?: number;
100	  onChange: (v: number) => void;
101	}
102	
103	function DollarField({
104	  label,
105	  tooltip,
106	  value,
107	  min = 0,
108	  onChange,
109	}: DollarFieldProps) {
110	  const inputId = useId();
111	
112	  return (
113	    <div className={styles.field}>
114	      <label htmlFor={inputId} className={styles.fieldLabel}>
115	        {label}
116	        <Tooltip text={tooltip} />
117	      </label>
118	      <div className={styles.dollarWrap}>
119	        <span className={styles.dollarSign} aria-hidden="true">
120	          $
121	        </span>
122	        <input
123	          id={inputId}
124	          type="number"
125	          min={min}
126	          value={value}
127	          onChange={(e) => {
128	            const parsed = parseFloat(e.target.value);
129	            if (!isNaN(parsed) && parsed >= min) onChange(parsed);
130	          }}
131	          className={styles.dollarInput}
132	        />
133	      </div>
134	    </div>
135	  );
136	}
137	
138	// ─── Metric card ──────────────────────────────────────────────────────────────
139	
140	interface MetricCardProps {
141	  label: string;
142	  value: string;
143	  sub?: string;
144	}
