158	export function RoiCalculator() {
159	  const [state, setState] = useState<CalcState>({
160	    billing: "monthly",
161	    plan: "growth",
162	    teamSize: 10,
163	    manualHours: 12,
164	    hourlyRate: 55,
165	    toolCost: 800,
166	  });
167	
168	  const teamSizeRef = useRef<HTMLInputElement | null>(null);
169	  const manualHoursRef = useRef<HTMLInputElement | null>(null);
170	
171	  // Keep range slider fill track in sync
172	  useEffect(() => {
173	    const el = teamSizeRef.current;
174	    if (!el) return;
175	    el.style.background = sliderBg(state.teamSize, 1, 200);
176	  }, [state.teamSize]);
177	
178	  useEffect(() => {
179	    const el = manualHoursRef.current;
180	    if (!el) return;
181	    el.style.background = sliderBg(state.manualHours, 1, 40);
182	  }, [state.manualHours]);
183	
184	  function patch(partial: Partial<CalcState>) {
185	    setState((prev) => ({ ...prev, ...partial }));
186	  }
187	
188	  function applyPreset(key: PresetKey) {
189	    setState((prev) => ({ ...prev, ...ROI_PRESETS[key] }));
190	  }
191	
192	  const result = useMemo<CalcResult>(() => {
193	    const bmo = PLAN_PRICE_MAP[state.plan][state.billing];
194	    const byr = bmo * 12;
195	    const laborSaved =
196	      state.manualHours * state.hourlyRate * state.teamSize * 52;
197	    const savings = laborSaved + state.toolCost;
198	    const net = savings - byr;
199	    const roi = byr > 0 ? (net / byr) * 100 : 0;
200	    const monthlyBenefit = savings / 12 - bmo;
201	    const hrsSaved = state.manualHours * state.teamSize * 52;
202	    const totalHrs = 40 * state.teamSize * 52;
203	    const prodGain = totalHrs > 0 ? (hrsSaved / totalHrs) * 100 : 0;
204	
205	    return {
206	      bmo,
207	      byr,
208	      laborSaved,
209	      savings,
210	      net,
211	      roi,
212	      monthlyBenefit,
213	      hrsSaved,
214	      prodGain,
215	    };
216	  }, [state]);
217	
218	  const netIsPositive = result.net >= 0;
219	
220	  const teamSizeId = useId();
221	  const manualHoursId = useId();
222	
223	  return (
224	    <section className={styles.section}>
