226	        {/* Header */}
227	        <div className={styles.header}>
228	          <div className={styles.eyebrowBadge}>ROI Calculator</div>
229	          <h2 className={styles.title}>
230	            See Your Real Savings Before You Commit
231	          </h2>
232	          <p className={styles.subtitle}>
233	            Adjust the inputs to match your team. We&apos;ll show exactly how
234	            much Boldteq saves you annually compared to hiring.
235	          </p>
236	        </div>
237	
238	        {/* Preset buttons */}
239	        <div className={styles.presets}>
240	          {(Object.keys(ROI_PRESETS) as PresetKey[]).map((key) => {
241	            const { label, emoji } = ROI_PRESET_META[key];
242	            const preset = ROI_PRESETS[key];
243	            const isActive =
244	              state.plan === preset.plan &&
245	              state.teamSize === preset.teamSize &&
246	              state.manualHours === preset.manualHours;
247	
248	            return (
249	              <button
250	                key={key}
251	                type="button"
252	                className={`${styles.presetBtn} ${isActive ? styles.presetBtnActive : ""}`}
253	                onClick={() => applyPreset(key)}
254	              >
255	                <span aria-hidden="true">{emoji}</span>
256	                <span>{label}</span>
257	              </button>
258	            );
259	          })}
260	        </div>
261	
262	        {/* Two-column layout */}
263	        <div className={styles.layout}>
264	          {/* LEFT: Inputs */}
265	          <div className={styles.leftPanel}>
266	            <div className={styles.panelTitle}>Tell us about your team</div>
267	
268	            {/* Plan Selection block */}
269	            <div className={styles.planBlock}>
270	              {/* Billing toggle */}
271	              <div className={styles.billingToggle}>
272	                {(Object.keys(BILLING_LABELS) as BillingPeriod[]).map((b) => (
273	                  <button
274	                    key={b}
275	                    type="button"
276	                    className={`${styles.billingBtn} ${state.billing === b ? styles.billingBtnActive : ""}`}
277	                    onClick={() => patch({ billing: b })}
278	                  >
279	                    <span>{BILLING_LABELS[b]}</span>
280	                    {BILLING_BADGES[b] && (
281	                      <span className={styles.billingBadge}>
282	                        {BILLING_BADGES[b]}
283	                      </span>
284	                    )}
285	                  </button>
286	                ))}
287	              </div>
288	
289	              {/* Plan buttons */}
290	              <div className={styles.planButtons}>
291	                {(Object.keys(PLAN_LABELS) as PlanKey[]).map((p) => (
292	                  <button
293	                    key={p}
294	                    type="button"
295	                    className={`${styles.planBtn} ${state.plan === p ? styles.planBtnActive : ""}`}
296	                    onClick={() => patch({ plan: p })}
297	                  >
298	                    <span className={styles.planBtnName}>
299	                      {PLAN_LABELS[p]}
300	                    </span>
301	                    <span className={styles.planBtnPrice}>
302	                      {fmt(PLAN_PRICE_MAP[p][state.billing])}/mo
303	                    </span>
304	                  </button>
305	                ))}
306	              </div>
307	            </div>
308	
309	            {/* Team size slider */}
310	            <div className={styles.field}>
311	              <div className={styles.fieldHeader}>
312	                <label htmlFor={teamSizeId} className={styles.fieldLabel}>
