316	                <span className={styles.badge}>{state.teamSize} people</span>
317	              </div>
318	              <input
319	                id={teamSizeId}
320	                ref={teamSizeRef}
321	                type="range"
322	                min={1}
323	                max={200}
324	                step={1}
325	                value={state.teamSize}
326	                onChange={(e) => patch({ teamSize: Number(e.target.value) })}
327	                className={styles.slider}
328	              />
329	              <div className={styles.sliderRange}>
330	                <span>1</span>
331	                <span>200</span>
332	              </div>
333	            </div>
334	
335	            {/* Hours per week slider */}
336	            <div className={styles.field}>
337	              <div className={styles.fieldHeader}>
338	                <label htmlFor={manualHoursId} className={styles.fieldLabel}>
339	                  Hours / week on manual tasks
340	                  <Tooltip text={ROI_FIELD_TOOLTIPS.manualHours} />
341	                </label>
342	                <span className={styles.badge}>{state.manualHours} hrs</span>
343	              </div>
344	              <input
345	                id={manualHoursId}
346	                ref={manualHoursRef}
347	                type="range"
348	                min={1}
349	                max={40}
350	                step={0.5}
351	                value={state.manualHours}
352	                onChange={(e) =>
353	                  patch({ manualHours: Number(e.target.value) })
354	                }
355	                className={styles.slider}
356	              />
357	              <div className={styles.sliderRange}>
358	                <span>1 hr</span>
359	                <span>40 hrs</span>
360	              </div>
361	            </div>
362	
363	            {/* Hourly rate dollar input */}
364	            <DollarField
365	              label="Average Hourly Rate"
366	              tooltip={ROI_FIELD_TOOLTIPS.hourlyRate}
367	              value={state.hourlyRate}
368	              min={10}
369	              onChange={(v) => patch({ hourlyRate: v })}
370	            />
371	
372	            {/* Tool cost dollar input */}
373	            <DollarField
374	              label="Annual Tool & Contractor Cost"
375	              tooltip={ROI_FIELD_TOOLTIPS.toolCost}
376	              value={state.toolCost}
377	              min={0}
378	              onChange={(v) => patch({ toolCost: v })}
379	            />
380	          </div>
381	
382	          {/* RIGHT: Results */}
383	          <div className={styles.rightPanel}>
384	            {/* Hero savings card */}
385	            <div className={styles.heroCard}>
386	              <div className={styles.heroLabel}>
387	                Your Estimated Annual Savings
388	              </div>
389	              <div
390	                className={`${styles.heroAmount} ${netIsPositive ? styles.heroAmountPositive : styles.heroAmountNegative}`}
391	              >
392	                {fmt(result.savings)}
393	              </div>
394	              <div className={styles.heroMeta}>
395	                <span
396	                  className={`${styles.roiPill} ${netIsPositive ? styles.roiPillPositive : styles.roiPillNegative}`}
397	                >
398	                  {fmtRoi(result.roi)} ROI
399	                </span>
400	                <span className={styles.heroSubLabel}>in the first year</span>
401	              </div>
402	            </div>
403	
404	            {/* Metrics grid */}
405	            <div className={styles.metricsGrid}>
406	              <MetricCard
407	                label="Hours Saved"
408	                value={fmtHrs(result.hrsSaved)}
409	                sub="annually"
410	              />
411	              <MetricCard
412	                label="Monthly Benefit"
413	                value={fmt(result.monthlyBenefit)}
414	                sub="after plan cost"
415	              />
416	              <MetricCard
417	                label="Productivity Boost"
418	                value={fmtPct(result.prodGain)}
419	                sub="of total work hrs"
420	              />
421	              <MetricCard
422	                label="Total Gain"
423	                value={fmt(result.net)}
424	                sub="net over plan cost"
425	              />
426	            </div>
427	
428	            {/* Plan summary */}
429	            <div className={styles.planSummary}>
430	              <div className={styles.summaryRow}>
431	                <span className={styles.summaryLabel}>What You&apos;ll Pay</span>
432	                <span className={styles.summaryValue}>
433	                  {fmt(result.byr)}/yr
434	                </span>
435	              </div>
436	              <div className={styles.summaryDivider} />
437	              <div className={styles.summaryRow}>
438	                <span className={styles.summaryLabel}>Money You Keep</span>
439	                <span
440	                  className={`${styles.summaryValue} ${netIsPositive ? styles.summaryPositive : styles.summaryNegative}`}
441	                >
442	                  {fmt(result.net)}
443	                </span>
444	              </div>
445	            </div>
446	
447	            {/* CTA card */}
448	            <div className={styles.ctaCard}>
449	              <div className={styles.ctaHeadline}>
450	                You could save{" "}
451	                <span className={styles.ctaHighlight}>
452	                  {fmt(result.savings)}
453	                </span>{" "}
454	                this year
455	              </div>
456	              <p className={styles.ctaSubtitle}>
457	                Stop paying {fmt(result.laborSaved)} in labor on tasks Boldteq
458	                handles end-to-end.
459	              </p>
460	              <a
461	                href="/book-a-demo"
462	                className={styles.ctaButton}
463	              >
464	                Schedule a Free Demo
465	              </a>
466	              <div className={styles.trustBadges}>
467	                <span className={styles.trustBadge}>14-day guarantee</span>
468	                <span className={styles.trustBadgeDot} aria-hidden="true" />
469	                <span className={styles.trustBadge}>No lock-in</span>
470	                <span className={styles.trustBadgeDot} aria-hidden="true" />
471	                <span className={styles.trustBadge}>Cancel anytime</span>
472	              </div>
473	            </div>
474	          </div>
475	        </div>
476	      </div>
477	    </section>
478	  );
479	}
